#include <iostream>
#include <fstream>
using namespace std;

int main() {
    // فائل کریئٹ کرکے رائٹ کرنا
    ofstream outFile("data.txt");
    outFile << "Hello, C++ File Handling!";
    outFile.close();

    // فائل ریڈ کرنا
    ifstream inFile("data.txt");
    string line;
    getline(inFile, line);
    cout << "File content: " << line << endl;
    inFile.close();
    return 0;
}
